from datetime import datetime
from typing import Any


def _datediff(today: str, open_date: Any) -> int:
    """Return whole calendar days between today and open_date."""
    if not today or not open_date:
        return 0

    today_text = str(today)
    open_text = str(open_date)

    if today_text == "00000000" or open_text == "00000000":
        return 0

    try:
        return (
            datetime.strptime(today_text, "%Y%m%d").date()
            - datetime.strptime(open_text, "%Y%m%d").date()
        ).days
    except ValueError:
        return 0


